// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 warpTime) public {
        vm.assume(warpTime > 0);
        vm.warp(warpTime);
        address sender = address(0x1234);
        vm.deal(sender, 20 ether);
        vm.startPrank(sender);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        vm.stopPrank();
        vm.warp(warpTime);
        vm.startPrank(sender);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        vm.stopPrank();
        assertTrue(!ok2);
    }
}
